module.exports = `(() => { const script = document.currentScript; const id = script?.dataset.widgetId || new URL(script.src).searchParams.get('id'); if (!id) return; const api = new URL(script.src).origin; fetch(api + '/public/widgets/' + encodeURIComponent(id) + '/config').then(r => r.ok ? r.json() : Promise.reject()).then(config => { const root = document.createElement('section'); root.className = 'lead-widget'; root.innerHTML = '<h3></h3><p></p><form></form>'; root.querySelector('h3').textContent = config.title; root.querySelector('p').textContent = config.description || ''; const form = root.querySelector('form'); config.fields.forEach(field => { const label = document.createElement('label'); label.textContent = field.label || field.name; const input = document.createElement(field.type === 'textarea' ? 'textarea' : 'input'); input.name = field.name; input.type = field.type === 'textarea' ? undefined : field.type; input.required = field.required; label.append(input); form.append(label); }); const trap = document.createElement('input'); trap.name = 'website'; trap.tabIndex = -1; trap.autocomplete = 'off'; trap.style.cssText = 'position:absolute;left:-9999px'; form.append(trap); const button = document.createElement('button'); button.textContent = config.buttonText; form.append(button); form.addEventListener('submit', async event => { event.preventDefault(); const data = Object.fromEntries(new FormData(form)); const response = await fetch(api + '/public/submissions', { method: 'POST', headers: {'Content-Type':'application/json', 'Idempotency-Key': crypto.randomUUID()}, body: JSON.stringify({widgetId: config.id, data, honeypot: data.website || ''}) }); form.textContent = response.ok ? 'Thanks - you are on the list.' : 'Please check your details and try again.'; }); script.parentNode.insertBefore(root, script.nextSibling); }); })();`;
